52	    /// Match against a list of matchers where negated matchers are handled as exceptions.
53	    /// Returns `default` if there is no matchers that match.
54	    pub fn matches_with_exceptions<'b, I>(&self, matchers: I) -> bool
55	    where
56	        I: IntoIterator<Item = &'b GroupMatcher>,
57	        I::IntoIter: DoubleEndedIterator,
58	    {
59	        // Iterate in reverse order to avoid unnecessary glob matching.
60	        for matcher in matchers.into_iter().rev() {
61	            if matcher.is_raw_match(self) {
62	                return !matcher.is_negated();
63	            }
64	        }
65	        false
66	    }
